select jsonb_build_object(
 'tables',(select jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl)order by c.relname)from pg_class c where c.relnamespace='public'::regnamespace and c.relname in('packing_items','packing_category_assignees','packing_categories','packing_category_assignments')),
 'columns',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid))order by c.relname,a.attnum)from pg_class c join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where c.relnamespace='public'::regnamespace and c.relname in('packing_items','packing_category_assignees','packing_categories','packing_category_assignments')),
 'constraints',(select jsonb_agg(jsonb_build_object('table',conrelid::regclass::text,'name',conname,'definition',pg_get_constraintdef(oid),'validated',convalidated)order by conrelid::regclass::text,conname)from pg_constraint where conrelid in('public.packing_items'::regclass,'public.packing_category_assignees'::regclass,'public.packing_categories'::regclass,'public.packing_category_assignments'::regclass)),
 'indexes',(select jsonb_agg(jsonb_build_object('table',tablename,'name',indexname,'definition',indexdef)order by tablename,indexname)from pg_indexes where schemaname='public'and tablename in('packing_items','packing_category_assignees','packing_categories','packing_category_assignments')),
 'policies',(select jsonb_agg(to_jsonb(p)order by tablename,policyname)from pg_policies p where schemaname='public'and tablename in('packing_items','packing_category_assignees','packing_categories','packing_category_assignments')),
 'triggers',(select jsonb_agg(jsonb_build_object('table',tgrelid::regclass::text,'name',tgname,'enabled',tgenabled,'definition',pg_get_triggerdef(oid))order by tgrelid::regclass::text,tgname)from pg_trigger where not tgisinternal and tgrelid in('public.packing_items'::regclass,'public.packing_category_assignees'::regclass,'public.packing_categories'::regclass,'public.packing_category_assignments'::regclass)),
 'function_contract',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'acl',p.proacl,'definer',p.prosecdef,'volatility',p.provolatile,'config',p.proconfig)order by p.oid::regprocedure::text)from pg_proc p where p.oid::regprocedure::text=any(array['build_family_export_v1(uuid)','family_auth.packing_category_can_read(uuid)','family_auth.packing_category_json(packing_categories)','family_auth.packing_category_resolve(uuid,uuid,text)','family_auth.packing_execute_entry(uuid,uuid,jsonb,text,uuid,bigint,bigint,jsonb)','family_auth.packing_group_selected(packing_items,jsonb)','family_auth.packing_item_json(packing_items)','family_auth.packing_snapshot(uuid)','family_auth.packing_with_categories_entry(uuid)','family_auth.tg_packing_category_assignment()','family_auth.tg_packing_category_bridge()','family_auth.tg_packing_category_changed()','family_auth.tg_packing_category_identity()','family_auth.tg_packing_category_link()','family_auth.tg_packing_category_lock()','family_auth.tg_packing_collection()','family_auth.tg_packing_person_context()','family_auth.tg_packing_version()','get_family_trip_packing_with_categories_v1(uuid)'])))::text;
